mapper.select:
/*流程中*/ SELECT DISTINCT T1.TOTLE_TRADE_ID id, T1.TOTLE_TRADE_ID text, T1.PORTFOLIO_ID FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN FIN_PRODUCT fp1 on fp1.FINPROD_ID = T1.CHL_ID LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T4.FINPROD_ID = T5.FINPROD_ID LEFT JOIN TRD_PRODUCT_DEAL ptpd on ptpd.TRADE_ID = T4.FINPROD_ID WHERE T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TGF02}, #{FINPROD_TYPE_TGF03}) and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_N} AND T1.P_TRADE_ID IS NULL/*撤销流程中的数据不展示*/ and T1.PORTFOLIO_ID
and (instr(T1.TOTLE_TRADE_ID, #{search}) > 0)
UNION ALL /*有效数据*/ SELECT DISTINCT T1.TOTLE_TRADE_ID id, T1.TOTLE_TRADE_ID text, PP.PORTFOLIO_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN FIN_PRODUCT fp1 on fp1.FINPROD_ID = T1.CHL_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T4.FINPROD_ID = T5.FINPROD_ID LEFT JOIN PTL_TRADE PT ON T1.FINPROD_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN TRD_PRODUCT_DEAL ptpd on ptpd.TRADE_ID = T4.FINPROD_ID WHERE PP.INVEST_YESORNO = 'Y' AND T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TGF02}, #{FINPROD_TYPE_TGF03}) and T1.PORTFOLIO_ID and t1.TRADE_STATUS = #{TRADE_STATUS01} and t1.IS_CANCEL = #{YES_OR_NO_N} and t1.PS in (#{PST07},#{PST56},#{PS_TQZZ},#{PS_YQFS})
and (instr(T1.TOTLE_TRADE_ID, #{search}) > 0)
/*撤销数据*/ UNION ALL SELECT DISTINCT T1.P_TRADE_ID id, T1.P_TRADE_ID text, PP.PORTFOLIO_ID FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN FIN_PRODUCT fp1 on fp1.FINPROD_ID = T1.CHL_ID LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T4.FINPROD_ID = T5.FINPROD_ID LEFT JOIN PTL_TRADE PT ON T1.FINPROD_ID = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PP ON PT.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN TRD_PRODUCT_DEAL ptpd on ptpd.TRADE_ID = T4.FINPROD_ID WHERE PP.INVEST_YESORNO = 'Y' AND T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TGF02}, #{FINPROD_TYPE_TGF03}) and T1.PORTFOLIO_ID and t1.TRADE_STATUS = #{TRADE_STATUS03} and t1.PS in (#{PST07},#{PST56},#{PS_TQZZ},#{PS_YQFS})
and (instr(T1.P_TRADE_ID, #{search}) > 0)

