select.if:
SELECT T1.TOTLE_TRADE_ID busiCode, T1.P_TRADE_ID, T1.CCY, T4.BASIS, T4.INT_RATE*100 INT_RATE, T1.COUNTER_ID, T6.COUNTER_NAME, T1.COUNTER_TRADER, T1.TRADER, T1.REMARK, T4.FINPROD_ID, T1.PORTFOLIO_ID, T2.PORTFOLIO_NAME, T5.TYPE_6,
T1.CHL_ID,
T1.FINPROD_TYPE2 , to_char(T1.TRADE_DATE, 'yyyy-MM-dd') TRADE_DATE, to_char(T1.VDATE, 'yyyy-MM-dd') vDate/*计息开始日*/, to_char(T1.MDATE, 'yyyy-MM-dd') mDate/*计息结束日*/, T4.TERM,/*回购期限*/ T3.THEORY_PRIN/*利息本金*/, T1.TRADE_MARKET TRADE_MARKET, to_char(T1.SETTLE_DATE, 'yyyy-MM-dd') SETTLE_DATE, T3.THEORY_INT/*理论利息*/, T3.THEORY_AMT/*理论本息总额*/, T1.TRADE_AMT/*实收本息总额*/,T1.WORKFLOW_ID, T1.FPRICE_AMT, T1.FEE_AMT channelFee FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN WFL_PA_TRD_FIN_DEAL_TOTAL T3 ON T1.TOTLE_TRADE_ID = T3.TOTLE_TRADE_ID LEFT JOIN PTL_PORTFOLIO T2 ON T2.PORTFOLIO_ID = T1.PORTFOLIO_ID LEFT JOIN FIN_TRADE_PRODUCT T4 ON T1.FINPROD_ID = T4.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE T5 ON T4.FINPROD_ID = T5.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY T6 ON T1.COUNTER_ID = T6.COUNTER_ID WHERE T1.TOTLE_TRADE_ID = #{busiCode}

mapper.select:
SELECT B.CASH_ID, B.CASH_TYPE
FROM FIN_CASH_INFO A LEFT JOIN FIN_CASH_PLAN B ON A.CASH_ID = B.CASH_ID
WHERE A.FINPROD_ID= #{finprodId}

select A.PROD_REGIST_CODE
from FIN_PRODUCT_ADD A inner join FIN_PRODUCT B
             on A.FINPROD_ID = B.FINPROD_ID
             and B.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F06}
WHERE B.FINPROD_MARKET_ID = #{portfolioId}

mapper.update:
UPDATE PTL_SEC_POSITION
SET AMOUNT = AMOUNT + #{amount},
UPDATE_TIME=#{updateTime, jdbcType=TIMESTAMP}
WHERE BRANCH = #{branch}
       AND SEC_ACCT_ID = #{secAcctId}
       AND CDATE = #{cdate}
       AND HODING_TYPE = #{hodingType}
       AND INV_AIM = #{invAim}
       AND PORTFOLIO_ID = #{portfolioId}
       AND FINPROD_ID = #{finprodId}

mapper.insert:
INSERT INTO PTL_SEC_POSITION_FLOW
(SEQNO, PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, BRANCH, HODING_TYPE, CDATE, CCY, AMOUNT,
P_FINPROD_ID, TRADE_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, INV_AIM)
select '${seqNo}', PORTFOLIO_ID, SEC_ACCT_ID, FINPROD_ID, BRANCH, HODING_TYPE, #{mDate, jdbcType=DATE}, CCY,

    AMOUNT*-1,


    AMOUNT,

P_FINPROD_ID, '${newTradeId}', CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME, INV_AIM
from PTL_SEC_POSITION_FLOW
where
    TRADE_ID = #{tradeId,jdbcType=VARCHAR}
    AND HODING_TYPE = #{holdingType}
    AND CDATE = #{vDate, jdbcType=DATE}
    AND FINPROD_ID = #{finprodId,jdbcType=VARCHAR}
